import{_ as s,C as c,o as n,c as l,j as e,a as d,E as o,aj as r}from"./chunks/framework.m090XgxO.js";const q=JSON.parse('{"title":"EmptyState","description":"","frontmatter":{},"headers":[],"relativePath":"components/empty-state.md","filePath":"components/empty-state.md","lastUpdated":1789206102000}'),h={name:"components/empty-state.md"},p={id:"emptystate",tabindex:"-1"};function m(u,t,b,y,f,x){const i=c("Badge"),a=c("XhDemo");return n(),l("div",null,[e("h1",p,[t[0]||(t[0]=d("EmptyState ",-1)),o(i,{type:"info",text:"空状态"}),t[1]||(t[1]=d()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#emptystate","aria-label":'Permalink to "EmptyState <Badge type="info" text="空状态" />"'},"​",-1))]),t[3]||(t[3]=r('<p>没有数据时那一块：说清楚为什么空，以及可以做什么。</p><p>空态与结果页共用一副骨架：图标、标题、说明、操作四段与整页结果完全一致，所以 404、403、500 这类结果页也用本组件铺。<code>status</code> 只落成 root 的 <code>data-status</code>，皮肤据它给图标区上语气色， 不改任何语义、不带插画资产。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/empty-state" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/empty-state.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/empty-state" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/empty-state" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/empty-state.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>图标、标题、说明、操作四个槽都可选，只有 root 是必须的</p>',5)),o(a,{src:"empty-state/01-basic"}),t[4]||(t[4]=e("h2",{id:"示例",tabindex:"-1"},[d("示例 "),e("a",{class:"header-anchor",href:"#示例","aria-label":'Permalink to "示例"'},"​")],-1)),t[5]||(t[5]=e("h3",{id:"尺寸",tabindex:"-1"},[d("尺寸 "),e("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[6]||(t[6]=e("p",null,"size 只换留白与字号，语义一点不动；不传即 md",-1)),o(a,{src:"empty-state/02-size"}),t[7]||(t[7]=e("h3",{id:"播报方式",tabindex:"-1"},[d("播报方式 "),e("a",{class:"header-anchor",href:"#播报方式","aria-label":'Permalink to "播报方式"'},"​")],-1)),t[8]||(t[8]=e("p",null,"缺省 polite 让 root 成为活区，筛完就地播报；off 让它只是个普通容器",-1)),o(a,{src:"empty-state/03-live"}),t[9]||(t[9]=e("h3",{id:"用作结果页",tabindex:"-1"},[d("用作结果页 "),e("a",{class:"header-anchor",href:"#用作结果页","aria-label":'Permalink to "用作结果页"'},"​")],-1)),t[10]||(t[10]=e("p",null,"同一套部件也承载 404、403 这类结果：status 给图标区上语气色，操作槽里放回退出口",-1)),o(a,{src:"empty-state/04-result"}),t[11]||(t[11]=e("h3",{id:"图标自带语气",tabindex:"-1"},[d("图标自带语气 "),e("a",{class:"header-anchor",href:"#图标自带语气","aria-label":'Permalink to "图标自带语气"'},"​")],-1)),t[12]||(t[12]=e("p",null,"图标槽里放一枚带 tone 的图标，着色落在图标自己身上，不经过 status",-1)),o(a,{src:"empty-state/05-tone-icon"}),t[13]||(t[13]=e("h3",{id:"结果类型",tabindex:"-1"},[d("结果类型 "),e("a",{class:"header-anchor",href:"#结果类型","aria-label":'Permalink to "结果类型"'},"​")],-1)),t[14]||(t[14]=e("p",null,"status 只落成 data-status，皮肤据它给图标区上语气色；画什么图标仍由作者塞",-1)),o(a,{src:"empty-state/06-status"}),t[15]||(t[15]=r('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>列表、表格、搜索结果为空。</li><li>首次使用、还没有任何数据。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>数据在加载中：用<a href="./skeleton">骨架屏</a>或<a href="./spinner">加载指示器</a>。</li><li>只是一次轻量操作的反馈：用<a href="./toast">轻提示</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>图标、标题、描述、操作四段都可选。</li><li><code>live</code> 决定这块内容出现时读屏怎么播报——搜索结果变空时这一条很重要。</li><li><code>status</code> 决定图标区并进哪一族语气色：三个状态码各并进最接近的一族，另有成功、警示、出错、提示四档。</li></ul><h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-empty-state&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhEmptyStateAction</code> <code>XhEmptyStateDescription</code> <code>XhEmptyStateIndicator</code> <code>XhEmptyStateMedia</code> <code>XhEmptyStateRoot</code> <code>XhEmptyStateTitle</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/empty-state.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;empty-state&quot;</code>：<strong><code>root</code></strong> · <code>media</code> · <code>indicator</code> · <code>title</code> · <code>description</code> · <code>action</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>live</code></td><td><code>EmptyStateLive</code></td><td></td><td>缺省 polite。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸档位，只改留白与字号，不改语义。</td></tr><tr><td><code>status</code></td><td><code>EmptyStateStatus</code></td><td></td><td>结果类型，只落成 root 的 data-status；图标画什么由作者塞进图标槽。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定用哪族颜色。不给即维持中性。</td></tr></tbody></table><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>connect</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>live</code></td><td><code>EmptyStateLive</code></td><td>生效的播报方式，缺省补齐后的值。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getMediaProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>插画槽：按自己的尺寸档量，与字形槽二选一。</td></tr><tr><td><code>getIndicatorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTitleProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getDescriptionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getActionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/practices/live-regions/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>role</code></td><td>undefined | &#39;status&#39;</td></tr><tr><td><code>media</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/empty-state.css</code> 按部件选择：<code>[data-scope=&quot;empty-state&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 与 <code>xihan.motion</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-status</code></td><td>props.status</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；缺省来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>缺省来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-empty-state-action-gap</code></td><td><code>action</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-2</code></td><td>empty-state 的 action 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-description-fg</code></td><td><code>description</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-muted</code></td><td>empty-state 的 description 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-description-font-size</code></td><td><code>description</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-body-size</code></td><td>empty-state 的 description 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-description-leading</code></td><td><code>description</code></td><td><code>line-height</code></td><td><code>default</code></td><td><code>--xh-text-body-leading</code></td><td>empty-state 的 description 部件 line-height 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-description-max-w</code></td><td><code>description</code></td><td><code>max-inline-size</code></td><td><code>default</code></td><td><code>--xh-measure-prose</code></td><td>empty-state 的 description 部件 max-inline-size 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-fg</code></td><td><code>root</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>empty-state 的 root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-gap</code></td><td><code>root</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-_empty-state-gap</code></td><td>empty-state 的 root 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-icon-size</code></td><td><code>indicator</code></td><td><code>--xh-icon-size</code><br><code>block-size</code><br><code>inline-size</code></td><td><code>default</code></td><td><code>--xh-_empty-state-icon-size</code></td><td>empty-state 的 indicator 部件 --xh-icon-size、block-size、inline-size 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-indicator-fg</code></td><td><code>indicator</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-_empty-state-accent</code></td><td>empty-state 的 indicator 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-indicator-font-size</code></td><td><code>indicator</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_empty-state-icon-size</code></td><td>empty-state 的 indicator 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-media-fg</code></td><td><code>media</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-_empty-state-accent</code></td><td>empty-state 的 media 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-media-size</code></td><td><code>media</code></td><td><code>block-size</code></td><td><code>default</code></td><td><code>--xh-_empty-state-icon-size</code></td><td>empty-state 的 media 部件 block-size 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-px</code></td><td><code>root</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-space-6</code></td><td>empty-state 的 root 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-py</code></td><td><code>root</code></td><td><code>padding-block</code></td><td><code>default</code></td><td><code>--xh-_empty-state-py</code></td><td>empty-state 的 root 部件 padding-block 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-title-fg</code></td><td><code>title</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>empty-state 的 title 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-title-font-size</code></td><td><code>title</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_empty-state-title-size</code></td><td>empty-state 的 title 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-title-font-weight</code></td><td><code>title</code></td><td><code>font-weight</code></td><td><code>default</code></td><td><code>--xh-font-weight-semibold</code></td><td>empty-state 的 title 部件 font-weight 覆盖槽。</td></tr><tr><td><code>--xh-empty-state-title-leading</code></td><td><code>title</code></td><td><code>line-height</code></td><td><code>default</code></td><td><code>--xh-leading-tight</code></td><td>empty-state 的 title 部件 line-height 覆盖槽。</td></tr></tbody></table><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>关键帧 <code>xh-rise-in</code> 随皮肤自带，不引用别处文件里的名字。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>图标用<a href="./icon-wrapper">图标块</a>；操作用<a href="./button">按钮</a>。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>区分三种空：从来没有、筛选之后没有、搜索没结果。三者该说的话完全不同。</li><li>给一条出路：新建、清除筛选、换个关键词。</li><li>用作结果页时每一页都给回退出口：回首页、重试、联系支持。403 与 500 尤其需要。</li><li>失败页给可追溯的标识（请求号、时间），用户报障时用得上。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>只画一个空盒子加&quot;暂无数据&quot;：用户不知道下一步做什么。</li><li>首次使用时的空状态跟筛选无结果长得一样。</li><li>只写&quot;出错了&quot;却不说是什么错，也不给下一步。</li></ul>',42))])}const k=s(h,[["render",m]]);export{q as __pageData,k as default};
